create table if not exists public.multiplayer_round_scores(id uuid primary key default gen_random_uuid(),match_id uuid not null references public.matches(id) on delete cascade,player_id uuid not null references auth.users(id) on delete cascade,question_index smallint not null,is_correct boolean not null,timed_out boolean not null,money_before bigint not null default 0,money_after bigint not null default 0,created_at timestamptz not null default now(),unique(match_id,player_id,question_index));
create table if not exists public.multiplayer_match_results(id uuid primary key default gen_random_uuid(),match_id uuid not null unique references public.matches(id) on delete cascade,winner_player_id uuid references auth.users(id),result_type text not null check(result_type in('win','draw','cancelled')),created_at timestamptz not null default now());
alter table public.multiplayer_round_scores enable row level security; alter table public.multiplayer_match_results enable row level security;
create policy score_read_member on public.multiplayer_round_scores for select using(exists(select 1 from public.match_members mm where mm.match_id=multiplayer_round_scores.match_id and mm.player_id=auth.uid()));
create policy result_read_member on public.multiplayer_match_results for select using(exists(select 1 from public.match_members mm where mm.match_id=multiplayer_match_results.match_id and mm.player_id=auth.uid()));
